// Internationalization service

export const EU_LANGUAGE_CODES = [
  'bg', 'cs', 'da', 'de', 'el', 'en', 'es', 'et', 'fi', 'fr', 'ga', 'hr',
  'hu', 'it', 'lt', 'lv', 'mt', 'nl', 'pl', 'pt', 'ro', 'sk', 'sl', 'sv',
] as const;

export type Language = (typeof EU_LANGUAGE_CODES)[number];

export const LANGUAGE_LABELS: Record<Language, string> = {
  bg: 'Български',
  cs: 'Čeština',
  da: 'Dansk',
  de: 'Deutsch',
  el: 'Ελληνικά',
  en: 'English',
  es: 'Español',
  et: 'Eesti',
  fi: 'Suomi',
  fr: 'Français',
  ga: 'Gaeilge',
  hr: 'Hrvatski',
  hu: 'Magyar',
  it: 'Italiano',
  lt: 'Lietuvių',
  lv: 'Latviešu',
  mt: 'Malti',
  nl: 'Nederlands',
  pl: 'Polski',
  pt: 'Português',
  ro: 'Română',
  sk: 'Slovenčina',
  sl: 'Slovenščina',
  sv: 'Svenska',
};

export function normalizeLanguage(raw: string | undefined | null): Language {
  const normalized = (raw ?? '').trim().toLowerCase().split(/[-_]/)[0];
  return EU_LANGUAGE_CODES.includes(normalized as Language) ? normalized as Language : 'en';
}

// Detect system language
export function detectLanguage(): Language {
  return normalizeLanguage(navigator.language);
}

