export function defaultCustomPrompt(lang: Language): string {
  return defaultCustomPrompts[lang] ?? defaultCustomPrompts.en;
}

export function defaultSystemPrompt(lang: Language): string {
  return defaultSystemPrompts[lang] ?? defaultSystemPrompts.en;
}

