  'onboarding.ollama.not_installed.desc': {
    bg: 'Ollama не е инсталиран на това устройство. Lingofix може автоматично да го изтегли и постави преносимо в директорията с данни на приложението – без нужда от администраторски права.',
    cs: 'Ollama není na tomto zařízení nainstalována. Lingofix ji může automaticky stáhnout a přenosně umístit do datového adresáře aplikace – nejsou potřeba práva správce.',
    da: 'Ollama er ikke installeret på denne enhed. Lingofix kan downloade den automatisk og placere den portabelt i appens datakatalog – ingen administratorrettigheder nødvendige.',
    de: 'Ollama ist auf diesem Gerät nicht installiert. Lingofix kann Ollama automatisch herunterladen und portable im App-Datenverzeichnis ablegen – ohne Admin-Rechte.',
    el: 'Το Ollama δεν είναι εγκατεστημένο σε αυτήν τη συσκευή. Το Lingofix μπορεί να το κατεβάσει αυτόματα και να το τοποθετήσει φορητά στον κατάλογο δεδομένων της εφαρμογής – δεν χρειάζονται δικαιώματα διαχειριστή.',
    en: 'Ollama is not installed on this device. Lingofix can download it automatically and place it portably in the app data directory – no admin rights needed.',
    es: 'Ollama no está instalado en este dispositivo. Lingofix puede descargarlo automáticamente y colocarlo de forma portátil en el directorio de datos de la aplicación – no se necesitan derechos de administrador.',
    et: 'Ollama ei ole sellele seadmele paigaldatud. Lingofix saab selle automaatselt alla laadida ja portatiivselt rakenduse andmekataloogi paigutada – administraatori õigusi ei ole vaja.',
    fi: 'Ollamaa ei ole asennettu tähän laitteeseen. Lingofix voi ladata sen automaattisesti ja sijoittaa sen kannettavasti sovelluksen tietohakemistoon – järjestelmänvalvojan oikeuksia ei tarvita.',
    fr: 'Ollama n’est pas installé sur cet appareil. Lingofix peut le télécharger automatiquement et le placer de manière portable dans le répertoire de données de l’application – aucun droit administrateur n’est requis.',
    ga: 'Níl Ollama suiteáilte ar an ngléas seo. Is féidir le Lingofix é a íoslódáil go huathoibríoch agus é a chur go inaistrithe i gcomhadlann sonraí na haipe – ní gá cearta riarthóra.',
    hr: 'Ollama nije instalirana na ovom uređaju. Lingofix je može automatski preuzeti i prenosivo smjestiti u direktorij podataka aplikacije – nisu potrebne administratorske ovlasti.',
    hu: 'Az Ollama nincs telepítve ezen az eszközön. A Lingofix automatikusan letöltheti és hordozható módon elhelyezheti az alkalmazás adatkönyvtárában – nincs szükség rendszergazdai jogokra.',
    it: 'Ollama non è installato su questo dispositivo. Lingofix può scaricarlo automaticamente e posizionarlo in modo portatile nella directory dei dati dell’app – non sono richiesti diritti di amministratore.',
    lt: 'Ollama neįdiegtas šiame įrenginyje. Lingofix gali jį automatiškai atsisiųsti ir nešiojamai patalpinti programėlės duomenų kataloge – administratoriaus teisės nereikalingos.',
    lv: 'Ollama šajā ierīcē nav instalēta. Lingofix to var automātiski lejupielādēt un pārnēsājami ievietot lietotnes datu direktorijā – administratora tiesības nav nepieciešamas.',
    mt: 'Ollama mhuwiex installat fuq dan l-apparat. Lingofix jista\' awtomatikament iniżżlu u jqiegħdu b\'mod portabbli fid-direttorju tad-dejta tal-app – mhumiex meħtieġa drittijiet tal-amministratur.',
    nl: 'Ollama is niet geïnstalleerd op dit apparaat. Lingofix kan het automatisch downloaden en draagbaar in de app-datamap plaatsen – geen beheerdersrechten nodig.',
    pl: 'Ollama nie jest zainstalowana na tym urządzeniu. Lingofix może ją automatycznie pobrać i umieścić przenośnie w katalogu danych aplikacji – nie są wymagane uprawnienia administratora.',
    pt: 'O Ollama não está instalado neste dispositivo. O Lingofix pode transferi-lo automaticamente e colocá-lo portavelmente na diretoria de dados da aplicação – não são necessários direitos de administrador.',
    ro: 'Ollama nu este instalat pe acest dispozitiv. Lingofix îl poate descărca automat și plasa portabil în directorul de date al aplicației – nu sunt necesare drepturi de administrator.',
    sk: 'Ollama nie je na tomto zariadení nainštalovaná. Lingofix ju môže automaticky stiahnuť a prenosne umiestniť do dátového adresára aplikácie – nie sú potrebné administrátorské práva.',
    sl: 'Ollama ni nameščen na tej napravi. Lingofix ga lahko samodejno prenese in prenosno namesti v podatkovni imenik aplikacije – skrbniška dovoljenja niso potrebna.',
    sv: 'Ollama är inte installerat på den här enheten. Lingofix kan ladda ner det automatiskt och placera det portabelt i appens datakatalog – inga administratörsrättigheter behövs.',
  },
