  'docx.openxml.accept_existing.message': {
    bg: 'В OpenXML режим корекцията може да продължи само ако Lingofix автоматично приеме всички съществуващи проследени промени преди корекцията.\n\nИскате ли да продължите?',
    cs: 'V režimu OpenXML může oprava pokračovat pouze tehdy, pokud Lingofix před opravou automaticky přijme všechny existující sledované změny.\n\nChcete pokračovat?',
    da: 'I OpenXML-tilstand kan rettelsen kun fortsætte, hvis Lingofix automatisk accepterer alle eksisterende sporede ændringer før rettelsen.\n\nVil du fortsætte?',
    de: 'Im OpenXML-Modus kann die Korrektur nur fortgesetzt werden, wenn Lingofix vorab alle vorhandenen Änderungen automatisch akzeptiert.\\\\n\\\\nMöchten Sie fortfahren?',
    el: 'Στη λειτουργία OpenXML, η διόρθωση μπορεί να συνεχιστεί μόνο εάν το Lingofix αποδεχτεί αυτόματα όλες τις υπάρχουσες παρακολουθούμενες αλλαγές πριν από τη διόρθωση.\n\nΘέλετε να συνεχίσετε;',
    en: 'In OpenXML mode, correction can continue only if Lingofix automatically accepts all existing tracked changes before correction.\\\\n\\\\nDo you want to continue?',
    es: 'En el modo OpenXML, la corrección solo puede continuar si Lingofix acepta automáticamente todos los cambios rastreados existentes antes de la corrección.\n\n¿Desea continuar?',
    et: 'OpenXML režiimis saab parandamine jätkuda ainult siis, kui Lingofix aktsepteerib enne parandamist automaatselt kõik olemasolevad jälgitavad muudatused.\n\nKas soovite jätkata?',
    fi: 'OpenXML-tilassa korjaus voi jatkua vain, jos Lingofix hyväksyy automaattisesti kaikki olemassa olevat seuratut muutokset ennen korjausta.\n\nHaluatko jatkaa?',
    fr: 'En mode OpenXML, la correction ne peut continuer que si Lingofix accepte automatiquement toutes les modifications suivies existantes avant la correction.\n\nVoulez-vous continuer ?',
    ga: 'I mód OpenXML, ní féidir an ceartú a leanúint ach amháin má ghlacann Lingofix go huathoibríoch leis na hathruithe rianaithe go léir atá ann cheana sula ndéantar an ceartú.\n\nAr mhaith leat leanúint ar aghaidh?',
    hr: 'U OpenXML načinu ispravljanje može nastaviti samo ako Lingofix automatski prihvati sve postojeće praćene promjene prije ispravljanja.\n\nŽelite li nastaviti?',
    hu: 'OpenXML módban a javítás csak akkor folytatódhat, ha a Lingofix a javítás előtt automatikusan elfogadja az összes meglévő követett változást.\n\nSzeretné folytatni?',
    it: 'In modalità OpenXML, la correzione può continuare solo se Lingofix accetta automaticamente tutte le modifiche tracciate esistenti prima della correzione.\n\nVuoi continuare?',
    lt: 'OpenXML režimu taisymas gali būti tęsiamas tik tuo atveju, jei Lingofix automatiškai priima visus esamus sekamus pakeitimus prieš taisymą.\n\nAr norite tęsti?',
    lv: 'OpenXML režīmā labošana var turpināties tikai tad, ja Lingofix pirms labošanas automātiski pieņem visas esošās izsekotās izmaiņas.\n\nVai vēlaties turpināt?',
    mt: 'Fil-modalità OpenXML, il-korrezzjoni tista\' tkompli biss jekk Lingofix awtomatikament jaċċetta l-bidliet kollha eżistenti segwiti qabel il-korrezzjoni.\n\nTrid tkompli?',
    nl: 'In OpenXML-modus kan de correctie alleen doorgaan als Lingofix automatisch alle bestaande bijgehouden wijzigingen accepteert vóór de correctie.\n\nWilt u doorgaan?',
    pl: 'W trybie OpenXML korekta może być kontynuowana tylko wtedy, gdy Lingofix automatycznie zaakceptuje wszystkie istniejące śledzone zmiany przed korektą.\n\nCzy chcesz kontynuować?',
    pt: 'No modo OpenXML, a correção só pode continuar se o Lingofix aceitar automaticamente todas as alterações controladas existentes antes da correção.\n\nDeseja continuar?',
    ro: 'În modul OpenXML, corectarea poate continua doar dacă Lingofix acceptă automat toate modificările urmărite existente înainte de corectare.\n\nDorești să continui?',
    sk: 'V režime OpenXML môže oprava pokračovať iba vtedy, ak Lingofix pred opravou automaticky prijme všetky existujúce sledované zmeny.\n\nChcete pokračovať?',
    sl: 'V načinu OpenXML lahko popravljanje nadaljuje le, če Lingofix pred popravljanjem samodejno sprejme vse obstoječe sledene spremembe.\n\nŽelite nadaljevati?',
    sv: 'I OpenXML-läge kan korrigeringen endast fortsätta om Lingofix automatiskt accepterar alla befintliga spårade ändringar före korrigeringen.\n\nVill du fortsätta?',
  },
